export function renderAppHtml({ supabaseUrl = "", publishableKey = "", transport = "proxy" } = {}) {
  if (transport !== "proxy" && transport !== "direct") throw new Error("Unsupported Lili Social transport");
  return ENHANCED_APP_TEMPLATE
    .replaceAll("__LILI_SUPABASE_URL__", supabaseUrl)
    .replaceAll("__LILI_SUPABASE_PUBLISHABLE_KEY__", publishableKey)
    .replaceAll("__LILI_TRANSPORT__", transport);
}

function json(data, status = 200) {
  return new Response(JSON.stringify(data), {
    status,
    headers: { "Content-Type": "application/json; charset=utf-8", "Cache-Control": "no-store" },
  });
}

function supabaseTarget(env, pathname, search) {
  const base = (env.SUPABASE_URL || FALLBACK_SUPABASE_URL).replace(/\/$/, "");
  const route = pathname.replace(/^\/api/, "") || "/";
  return base + route + search;
}

async function forward(request, env, targetPath) {
  const headers = new Headers(request.headers);
  const key = env.SUPABASE_PUBLISHABLE_KEY || env.SUPABASE_ANON_KEY || "";
  headers.set("apikey", key);
  if (targetPath === "/auth/v1/token" || targetPath === "/auth/v1/recover") {
    headers.set("Authorization", "Bearer " + key);
  }
  headers.delete("host");
  const init = { method: request.method, headers, redirect: "follow" };
  if (!["GET", "HEAD"].includes(request.method)) init.body = await request.arrayBuffer();
  const target = supabaseTarget(env, targetPath, new URL(request.url).search);
  try {
    const response = await fetch(target, init);
    const outHeaders = new Headers(response.headers);
    outHeaders.set("Cache-Control", "no-store");
    return new Response(response.body, { status: response.status, headers: outHeaders });
  } catch {
    return json({ error: "Supabase no respondió", message: "El servidor de acceso no respondió. Intenta nuevamente en unos segundos." }, 502);
  }
}

export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    if (request.method === "OPTIONS") return new Response(null, { status: 204 });
    if (url.pathname === "/" || url.pathname === "/index.html") {
      return new Response(renderAppHtml({
        supabaseUrl: env.SUPABASE_URL || FALLBACK_SUPABASE_URL,
        transport: "proxy",
      }), { headers: { "Content-Type": "text/html; charset=utf-8", "Cache-Control": "no-store" } });
    }
    if (url.pathname === "/api/auth/login") return forward(request, env, "/auth/v1/token");
    if (url.pathname === "/api/auth/recover") return forward(request, env, "/auth/v1/recover");
    if (url.pathname === "/api/auth/user") return forward(request, env, "/auth/v1/user");
    if (url.pathname.startsWith("/api/rest/")) return forward(request, env, url.pathname.replace("/api/rest", "/rest"));
    if (url.pathname.startsWith("/api/storage/")) return forward(request, env, url.pathname.replace("/api/storage", "/storage"));
    if (url.pathname.startsWith("/api/functions/")) return forward(request, env, url.pathname.replace("/api/functions", "/functions/v1"));
    return json({ error: "Not found" }, 404);
  },
};
